  "appearance_facts": [
    {
      "location": "top-left",
      "fact": "A large bold title spans the upper area, reading 'Declining Emergency Department Visits in Region Z from 2012 to 2023'. Below it is a smaller gray subtitle line."
    },
    {
      "location": "center plot",
      "fact": "A single dark-red line chart runs left to right across the plot from the 2012 x-position to the 2023 x-position."
    },
    {
      "location": "line trajectory",
      "fact": "The line starts low near the 1200 level at 2012, rises gently to a local peak near 2014, dips slightly at 2015, then climbs more steeply through 2017-2018, plateaus through 2019-2020, jumps sharply at 2021-2022 to the highest point, and ends slightly lower at 2023."
    },
    {
      "location": "right side of plot",
      "fact": "The 2022 point is the visual maximum of the line, sitting above the 3200 gridline; the 2023 point is just below the 3200 gridline."
    },
    {
      "location": "left side of plot",
      "fact": "The 2012-2015 segment of the line sits between the 800 and 1600 gridlines, clearly lower than the 2021-2023 segment."
    },
    {
      "location": "plot background",
      "fact": "Horizontal light-gray gridlines are visible at the 800, 1600, 2400, and 3200 y-levels; there are no vertical gridlines."
    },
    {
      "location": "axes",
      "fact": "A vertical y-axis line is on the left and a horizontal x-axis line is at the bottom; no legend box is present."
    },
    {
      "location": "data markers",
      "fact": "No point markers or data labels are drawn on the line; values must be inferred from gridline alignment."
    }
  ],
